--
-- Name: websites; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.websites (
    id integer NOT NULL,
    title text NOT NULL,
    slug text NOT NULL,
    description text,
    meta_title text,
    meta_description text,
    meta_keywords text,
    grapes_data jsonb DEFAULT '{}'::jsonb NOT NULL,
    grapes_html text,
    grapes_css text,
    grapes_js text,
    favicon text,
    custom_css text,
    custom_js text,
    custom_head text,
    status text DEFAULT 'draft'::text NOT NULL,
    published_at timestamp without time zone,
    google_analytics_id text,
    facebook_pixel_id text,
    template_id integer,
    theme text DEFAULT 'default'::text,
    created_by_id integer NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT websites_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'archived'::text])))
);


